import { Args } from '@oclif/core';
import { errorMessage, validateDefinitionInputs } from '@sanity/workflow-engine';
import logSymbols from 'log-symbols';
import { WorkflowCommand } from '../../../lib/base-command.js';
import { describeValidation, readDefinitionFiles } from '../../../lib/definition-files.js';
import { fail } from '../../../lib/fail.js';
import { jsonFlags } from '../../../lib/flags.js';
export default class DefinitionValidate extends WorkflowCommand {
    static hiddenAliases = ['workflows:definition:validate'];
    static description = 'Validate workflow definitions in JSON files without a config, login, or network access. Checks shape, cross-field rules, and GROQ syntax; deploy additionally checks duplicate names, spawn dependencies, resource bindings, project roles, and the reader-model acknowledgement. Exits non-zero when any definition is invalid. A file that cannot be read, is not valid JSON, or does not hold definition objects stops the command with an error message instead of a report, including with --json.';
    static examples = [
        '<%= config.bin %> workflows definitions validate review.json',
        '<%= config.bin %> workflows definitions validate parent.json child.json',
        '<%= config.bin %> workflows definitions validate review.json --json',
    ];
    static strict = false;
    static args = {
        file: Args.string({
            required: true,
            description: 'JSON file holding one definition or an array of them. Pass several files to validate a parent and its child workflows together.',
        }),
    };
    static flags = { ...jsonFlags };
    async run() {
        const { argv, flags } = await this.parse(DefinitionValidate);
        const paths = argv.map(String);
        let entries;
        try {
            entries = await readDefinitionFiles(paths);
        }
        catch (err) {
            fail('Could not read definitions:', errorMessage(err));
        }
        const report = validateDefinitionInputs(entries.map((entry) => entry.definition));
        if (flags.json) {
            this.log(JSON.stringify(report, null, 2));
            if (!report.valid) {
                this.exit(1);
            }
            return;
        }
        const { passed, failed } = describeValidation(entries, report);
        for (const line of passed) {
            this.log(`${logSymbols.success} ${line}`);
        }
        if (failed.length > 0) {
            fail(`${failed.length} of ${entries.length} definitions failed validation:`, failed.join('\n'));
        }
    }
}
